//! The Odyssey game data in `data/catalog/odyssey.json` (generated by `scripts/gen-odyssey.py`
//! from the Elite Dangerous Wiki and EDCD/FDevIDs): micro-resources with bartender values, suit
//! and weapon grade upgrades, modifications, and the on-foot engineers.

use serde::{Deserialize, Serialize};
use std::collections::BTreeMap;

/// Item symbol (journal `Name`, lowercase) → count.
pub type Materials = BTreeMap<String, i64>;

#[derive(Debug, Clone, Deserialize)]
pub struct Item {
    pub name: String,
    /// FDevIDs category: `item` (goods), `component` (assets), `data` or `consumable`.
    pub category: String,
    /// Bartender barter value; the wiki gives it for assets only.
    pub barter: Option<i64>,
    /// Credits a bartender pays for one.
    pub value: Option<i64>,
}

#[derive(Debug, Clone, Deserialize)]
pub struct Upgrade {
    /// The grade this step reaches (2 to 5).
    pub grade: u8,
    pub materials: Materials,
    /// `None` where the wiki leaves the price blank.
    pub credits: Option<i64>,
}

/// A suit or a handheld weapon, upgraded a grade at a time at Pioneer Supplies.
#[derive(Debug, Clone, Deserialize)]
pub struct Gear {
    pub id: String,
    pub name: String,
    /// Weapons only: `kinematic`, `manticore` or `takada` (modification costs differ by maker).
    #[serde(default)]
    pub maker: Option<String>,
    pub upgrades: Vec<Upgrade>,
}

#[derive(Debug, Clone, Deserialize)]
pub struct ModCost {
    /// `None`: the same cost for every weapon (and every suit).
    pub maker: Option<String>,
    pub materials: Materials,
    pub credits: Option<i64>,
}

/// A suit or weapon modification, fitted by an on-foot engineer.
#[derive(Debug, Clone, Deserialize)]
pub struct Modification {
    pub id: String,
    pub name: String,
    /// `suit` or `weapon`.
    pub kind: String,
    pub costs: Vec<ModCost>,
}

impl Modification {
    /// The cost for a weapon from `maker`; the shared cost when there is one.
    pub fn cost(&self, maker: Option<&str>) -> Option<&ModCost> {
        self.costs
            .iter()
            .find(|c| c.maker.is_none())
            .or_else(|| self.costs.iter().find(|c| c.maker.as_deref() == maker))
    }
}

#[derive(Debug, Clone, Deserialize, Serialize)]
pub struct Engineer {
    pub id: i64,
    pub name: String,
    pub system: String,
    pub id64: i64,
    pub colonia: bool,
    /// Modification ids.
    pub mods: Vec<String>,
    /// Mods the wiki's tables and mod pages disagree on for this engineer.
    pub unconfirmed_mods: Vec<String>,
    /// Engineers whose referral reveals this one (all of them, for Yi Shen).
    pub referred_by: Vec<String>,
    /// What earns the invitation.
    pub invite: String,
    /// What earns the referral to the engineers this one refers, if any.
    pub referral_task: Option<String>,
}

#[derive(Debug, Deserialize)]
pub struct Catalog {
    pub source: String,
    pub generated: String,
    pub items: BTreeMap<String, Item>,
    pub suits: Vec<Gear>,
    pub weapons: Vec<Gear>,
    pub mods: Vec<Modification>,
    pub engineers: Vec<Engineer>,
    pub uncertain: Vec<String>,
}

impl Catalog {
    pub fn gear(&self, id: &str) -> Option<&Gear> {
        self.suits.iter().chain(&self.weapons).find(|g| g.id == id)
    }

    pub fn is_suit(&self, id: &str) -> bool {
        self.suits.iter().any(|g| g.id == id)
    }

    pub fn modification(&self, id: &str) -> Option<&Modification> {
        self.mods.iter().find(|m| m.id == id)
    }

    pub fn item_name(&self, id: &str) -> String {
        self.items.get(id).map_or_else(|| id.to_string(), |i| i.name.clone())
    }
}

pub fn catalog() -> &'static Catalog {
    static C: std::sync::OnceLock<Catalog> = std::sync::OnceLock::new();
    C.get_or_init(|| serde_json::from_str(include_str!("../../../data/catalog/odyssey.json")).expect("odyssey.json"))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn catalogue_is_complete_and_consistent() {
        let c = catalog();
        assert_eq!(c.suits.len(), 3);
        assert_eq!(c.weapons.len(), 11);
        assert_eq!(c.mods.iter().filter(|m| m.kind == "suit").count(), 14);
        assert_eq!(c.mods.iter().filter(|m| m.kind == "weapon").count(), 11);
        assert_eq!(c.engineers.len(), 13);
        for g in c.suits.iter().chain(&c.weapons) {
            assert_eq!(g.upgrades.iter().map(|u| u.grade).collect::<Vec<_>>(), [2, 3, 4, 5], "{}", g.name);
            for u in &g.upgrades {
                assert!(u.materials.keys().all(|k| c.items.contains_key(k)), "{} grade {}", g.name, u.grade);
            }
        }
        for w in &c.weapons {
            let maker = w.maker.as_deref();
            assert!(matches!(maker, Some("kinematic" | "manticore" | "takada")), "{}", w.name);
            for m in c.mods.iter().filter(|m| m.kind == "weapon") {
                assert!(m.cost(maker).is_some(), "{} on {}", m.name, w.name);
            }
        }
        for m in &c.mods {
            for cost in &m.costs {
                assert!(cost.materials.keys().all(|k| c.items.contains_key(k)), "{}", m.name);
            }
        }
        for e in &c.engineers {
            assert!(e.mods.iter().all(|m| c.modification(m).is_some()), "{}", e.name);
            assert!(e.referred_by.iter().all(|r| c.engineers.iter().any(|x| &x.name == r)), "{}", e.name);
        }
    }

    #[test]
    fn known_wiki_values() {
        let c = catalog();
        // Maverick grade 2: 1 Suit Schematic, 1 Health Monitor, 1 Manufacturing Instructions,
        // 2 Carbon Fibre Plating, 2 Graphene, 600,000 CR.
        let g2 = &c.gear("maverick").unwrap().upgrades[0];
        assert_eq!(g2.materials["graphene"], 2);
        assert_eq!(g2.materials["suitschematic"], 1);
        assert_eq!(g2.credits, Some(600_000));
        assert_eq!(c.items["graphene"].barter, Some(23));
        assert_eq!(c.items["graphene"].value, Some(1300));
        // Headshot Damage costs differ by maker.
        let hs = c.modification("headshotdamage").unwrap();
        assert_ne!(hs.cost(Some("takada")).unwrap().materials, hs.cost(Some("manticore")).unwrap().materials);
        let yi = c.engineers.iter().find(|e| e.name == "Yi Shen").unwrap();
        assert_eq!(yi.referred_by, ["Baltanos", "Eleanor Bresa", "Rosa Dayette"]);
    }
}
